insert into public.character_archive (id, character_type, payload, sort_order) values
('survivors:dwight-fairfield', 'survivors', '["Dwight Fairfield","Easy","Bond · Prove Thyself · Leader","Team Support","A nervous but dependable leader who helps teammates coordinate and work efficiently.","Bond reveals nearby teammates, Prove Thyself rewards cooperative repairs, and Leader improves nearby teammates’ action speed.","Original"]'::jsonb, 0),
('survivors:meg-thomas', 'survivors', '["Meg Thomas","Easy","Quick & Quiet · Sprint Burst · Adrenaline","Escape & Chase","A competitive runner whose athletic instincts make her effective at creating distance from the Killer.","Quick & Quiet hides loud vaults and locker entries, Sprint Burst gives a burst of speed when running, and Adrenaline provides a late-trial recovery and speed boost.","Original"]'::jsonb, 1),
('survivors:claudette-morel', 'survivors', '["Claudette Morel","Easy","Empathy · Botany Knowledge · Self-Care","Healing & Support","A compassionate botany student with a strong focus on keeping the team healthy.","Empathy reveals injured teammates, Botany Knowledge improves healing efficiency, and Self-Care allows her to heal herself without a teammate.","Original"]'::jsonb, 2),
('survivors:jake-park', 'survivors', '["Jake Park","Intermediate","Iron Will · Calm Spirit · Saboteur","Stealth & Rescue","A self-reliant outdoorsman who prefers quiet movement and clever ways to support the team.","Iron Will reduces pain sounds, Calm Spirit helps avoid startling nearby wildlife, and Saboteur reveals hook auras and enables hook sabotage.","Original"]'::jsonb, 3),
('survivors:nea-karlsson', 'survivors', '["Nea Karlsson","Intermediate","Balanced Landing · Urban Evasion · Streetwise","Stealth & Mobility","A street-smart urban explorer who uses the environment to stay one step ahead.","Balanced Landing reduces the penalty after a fall, Urban Evasion speeds up crouching, and Streetwise improves item efficiency.","Original"]'::jsonb, 4),
('survivors:laurie-strode', 'survivors', '["Laurie Strode","Hard","Sole Survivor · Object of Obsession · Decisive Strike","Anti-Tunnel","A determined survivor known for refusing to give up when danger closes in.","Her perks focus on awareness, the Obsession mechanic, and a chance to escape the Killer’s grasp after being rescued.","Halloween"]'::jsonb, 5),
('survivors:ace-visconti', 'survivors', '["Ace Visconti","Easy","Open-Handed · Up the Ante · Ace in the Hole","Team Utility & Items","A charming gambler whose luck and confidence can benefit the whole team.","Open-Handed extends aura-reading ranges, Up the Ante improves team luck, and Ace in the Hole can add useful add-ons to found items.","Original"]'::jsonb, 6),
('survivors:bill-overbeck', 'survivors', '["Bill Overbeck","Hard","Left Behind · Borrowed Time · Unbreakable","Endgame & Rescue","A battle-hardened veteran who puts the team first, especially when a trial is nearly over.","Left Behind helps locate the final generator, Borrowed Time protects rescued teammates, and Unbreakable improves recovery from the dying state.","Left 4 Dead"]'::jsonb, 7),
('survivors:feng-min', 'survivors', '["Feng Min","Easy","Technician · Lithe · Alert","Stealth & Chase","A focused gamer whose quick reactions help her adapt under pressure.","Technician can reduce repair noise, Lithe grants a speed burst after a rushed vault, and Alert reveals the Killer after certain actions.","Original"]'::jsonb, 8),
('survivors:david-king', 'survivors', '["David King","Intermediate","We’re Gonna Live Forever · Dead Hard · No Mither","Protection & Chase","A tough fighter who excels at taking risks and protecting teammates.","His perks reward altruistic actions, provide a timed dodge after being injured, and offer a challenging high-risk recovery playstyle.","Original"]'::jsonb, 9),
('survivors:quentin-smith', 'survivors', '["Quentin Smith","Easy","Wake Up! · Pharmacy · Vigil","Recovery & Endgame","A resourceful insomniac who specializes in finding supplies and helping the team recover.","Wake Up! helps locate exit gates, Pharmacy improves access to medical supplies, and Vigil shortens the duration of several status effects.","A Nightmare on Elm Street"]'::jsonb, 10),
('survivors:david-tapp', 'survivors', '["David Tapp","Intermediate","Tenacity · Detective’s Hunch · Stake Out","Objectives & Tracking","A persistent detective who uses careful observation to uncover objectives.","Tenacity helps him crawl and recover, Detective’s Hunch reveals nearby objectives after a generator is completed, and Stake Out rewards staying near the Killer.","SAW"]'::jsonb, 11),
('survivors:kate-denson', 'survivors', '["Kate Denson","Easy","Dance With Me · Windows of Opportunity · Boil Over","Chase & Awareness","A travelling musician who turns map knowledge and quick movement into an advantage.","Dance With Me hides scratch marks after certain vaults, Windows of Opportunity reveals nearby vaults and pallets, and Boil Over makes carrying her more difficult.","Original"]'::jsonb, 12),
('survivors:adam-francis', 'survivors', '["Adam Francis","Intermediate","Diversion · Deliverance · Autodidact","Rescue & Healing","A dedicated teacher who brings patience and unconventional rescue tactics to the trial.","Diversion creates a sound distraction, Deliverance can enable a self-rescue after a safe rescue, and Autodidact improves healing skill checks over time.","Original"]'::jsonb, 13),
('survivors:jeff-johansen', 'survivors', '["Jeff Johansen","Intermediate","Breakdown · Aftercare · Distortion","Team Support & Stealth","A quiet artist whose perks help teammates share information and avoid being tracked.","Breakdown damages the hook used, Aftercare links aura information with teammates, and Distortion hides his aura and scratch marks from the Killer.","Original"]'::jsonb, 14),
('survivors:jane-romero', 'survivors', '["Jane Romero","Intermediate","Solidarity · Poised · Head On","Healing & Chase","A confident television host who can turn pressure into opportunities for bold plays.","Solidarity converts some self-healing progress into teammate healing, Poised hides scratch marks after a generator is completed, and Head On enables a locker-based stun.","Original"]'::jsonb, 15),
('survivors:ash-williams', 'survivors', '["Ash Williams","Easy","Flip-Flop · Buckle Up · Mettle of Man","Protection & Recovery","A wisecracking survivor with a stubborn instinct to keep fighting.","Flip-Flop converts recovery progress while carried, Buckle Up helps coordinate rescues, and Mettle of Man rewards taking protection hits.","Evil Dead"]'::jsonb, 16),
('survivors:nancy-wheeler', 'survivors', '["Nancy Wheeler","Easy","Better Together · Fixated · Inner Strength","Objectives & Stealth","An investigative student who combines objective awareness with a way to recover.","Better Together shares generator information, Fixated improves walking speed and scratch-mark awareness, and Inner Strength enables healing after cleansing a totem.","Stranger Things"]'::jsonb, 17),
('survivors:steve-harrington', 'survivors', '["Steve Harrington","Easy","Babysitter · Camaraderie · Second Wind","Rescue & Support","A protective friend who specializes in helping teammates after a hook rescue.","Babysitter helps conceal a rescued teammate, Camaraderie can pause hook struggle progression when an ally is nearby, and Second Wind provides delayed recovery after healing others.","Stranger Things"]'::jsonb, 18),
('survivors:yui-kimura', 'survivors', '["Yui Kimura","Intermediate","Lucky Break · Any Means Necessary · Breakout","Chase & Rescue","A motorcycle racer whose resourcefulness helps her improvise during a chase.","Lucky Break hides blood and scratch marks for a limited time, Any Means Necessary resets dropped pallets, and Breakout helps carried teammates struggle free.","Original"]'::jsonb, 19),
('survivors:zarina-kassir', 'survivors', '["Zarina Kassir","Intermediate","Off the Record · Red Herring · For the People","Stealth & Rescue","A documentary filmmaker who takes calculated risks to protect others.","Off the Record helps conceal her after being unhooked, Red Herring creates a generator-based distraction, and For the People enables a risky instant heal on a teammate.","Original"]'::jsonb, 20),
('survivors:cheryl-mason', 'survivors', '["Cheryl Mason","Easy","Soul Guard · Blood Pact · Repressed Alliance","Protection & Teamwork","A resilient survivor whose unusual experiences have prepared her for the Fog.","Soul Guard grants protection in specific recovery situations, Blood Pact links her aura with the Obsession, and Repressed Alliance can temporarily block a generator.","Silent Hill"]'::jsonb, 21),
('survivors:felix-richter', 'survivors', '["Felix Richter","Intermediate","Visionary · Desperate Measures · Built to Last","Objectives & Items","An inventive architect who plans ahead and makes efficient use of equipment.","Visionary reveals nearby generators, Desperate Measures improves healing and unhooking speed when teammates are injured, and Built to Last replenishes item charges while hidden in a locker.","Original"]'::jsonb, 22),
('survivors:elodie-rakoto', 'survivors', '["Élodie Rakoto","Intermediate","Appraisal · Deception · Power Struggle","Items & Escape","An adventurous researcher who relies on clever tricks and improvisation.","Appraisal searches chests again, Deception creates a misleading locker interaction, and Power Struggle can drop a pallet while being carried.","Original"]'::jsonb, 23),
('survivors:yun-jin-lee', 'survivors', '["Yun-Jin Lee","Easy","Fast Track · Smash Hit · Self-Preservation","Chase & Team Utility","A driven music producer who turns setbacks into momentum.","Fast Track gains repair progress when teammates are hooked, Smash Hit grants a speed burst after a pallet stun, and Self-Preservation hides certain injury cues when a nearby teammate is hit.","Original"]'::jsonb, 24),
('survivors:jill-valentine', 'survivors', '["Jill Valentine","Intermediate","Counterforce · Resurgence · Blast Mine","Objectives & Protection","A highly trained responder who stays composed and helps the team counter threats.","Counterforce speeds up totem cleansing, Resurgence grants healing progress after being unhooked, and Blast Mine traps a repaired generator to stun the Killer.","Resident Evil"]'::jsonb, 25),
('survivors:leon-s-kennedy', 'survivors', '["Leon S. Kennedy","Intermediate","Bite the Bullet · Flashbang · Rookie Spirit","Stealth & Objectives","A rookie police officer turned survivor who uses quick thinking to support the group.","Bite the Bullet quiets healing, Flashbang creates a temporary distraction, and Rookie Spirit reveals regressing generators after completing enough repairs.","Resident Evil"]'::jsonb, 26),
('survivors:mikaela-reid', 'survivors', '["Mikaela Reid","Intermediate","Clairvoyance · Boon: Circle of Healing · Boon: Shadow Step","Totems & Support","A spiritual young woman whose boon abilities create helpful zones for the team.","Clairvoyance reveals distant objectives after cleansing a totem, while her two Boon perks create totems that support healing and concealment.","Original"]'::jsonb, 27),
('survivors:jonah-vasquez', 'survivors', '["Jonah Vasquez","Easy","Overcome · Corrective Action · Boon: Exponential","Team Support & Recovery","A mathematician who applies analytical thinking to dangerous situations.","Overcome creates distance after being injured, Corrective Action can correct teammates’ failed skill checks, and Boon: Exponential improves recovery in its area.","Original"]'::jsonb, 28),
('survivors:yoichi-asakawa', 'survivors', '["Yoichi Asakawa","Intermediate","Parental Guidance · Empathic Connection · Boon: Dark Theory","Stealth & Support","A survivor with a connection to the supernatural who helps teammates move and recover.","Parental Guidance hides traces after stunning the Killer, Empathic Connection reveals his aura to injured teammates and improves healing, and Boon: Dark Theory grants a movement benefit in its area.","Ringu"]'::jsonb, 29),
('killers:the-trapper', 'killers', '["The Trapper","Evan MacMillan","Easy","Bear Traps","A territorial hunter who places concealed traps to control paths and punish careless movement.","Place and maintain bear traps around loops, chokepoints, and objectives. Survivors can disarm or escape them.","Unnerving Presence · Brutal Strength · Agitation","Original"]'::jsonb, 0),
('killers:the-wraith', 'killers', '["The Wraith","Philip Ojomo","Intermediate","Wailing Bell","A stealth-focused Killer who can cloak and move around the map with reduced visibility.","Ring the Wailing Bell to cloak, reposition, and approach survivors. Uncloaking reveals him before he attacks.","Predator · Bloodhound · Shadowborn","Original"]'::jsonb, 1),
('killers:the-hillbilly', 'killers', '["The Hillbilly","Max Thompson Jr.","Easy","Chainsaw","A high-mobility Killer who uses a chainsaw to rush across the map.","Charge the chainsaw to sprint in a straight path. Collisions and tight turns require careful control.","Enduring · Lightborn · Tinkerer","Original"]'::jsonb, 2),
('killers:the-nurse', 'killers', '["The Nurse","Sally Smithson","Hard","Spencer’s Last Breath","A high-skill Killer who can blink through obstacles and rapidly close distance.","Charge a blink to travel through obstacles, then use a follow-up blink or attack. Timing and prediction are essential.","Stridor · Thanatophobia · A Nurse’s Calling","Original"]'::jsonb, 3),
('killers:the-shape', 'killers', '["The Shape","Michael Myers","Hard","Evil Within","A stalking Killer who grows more dangerous by observing survivors.","Stalk survivors to build Evil Within tiers, changing his movement and attack threat as the power increases.","Save the Best for Last · Play with Your Food · Dying Light","Halloween"]'::jsonb, 4),
('killers:the-hag', 'killers', '["The Hag","Lisa Sherwood","Intermediate","Blackened Catalyst","A trap-setting Killer who uses mystical marks to create surprise approaches.","Draw Phantasm Traps on the ground. When triggered, she can teleport to the trap and pressure the survivor.","Hex: The Third Seal · Hex: Ruin · Hex: Devour Hope","Original"]'::jsonb, 5),
('killers:the-doctor', 'killers', '["The Doctor","Herman Carter","Hard","Carter’s Spark","A tracking-focused Killer who uses electrical shocks to build Madness and disrupt survivors.","Use Shock Therapy and Static Blast to increase Madness, interrupt actions, and reveal survivor positions.","Overwhelming Presence · Monitor & Abuse · Overcharge","Original"]'::jsonb, 6),
('killers:the-huntress', 'killers', '["The Huntress","Anna","Intermediate","Hunting Hatchets","A ranged Killer who throws hatchets to threaten survivors from a distance.","Collect hatchets from lockers and aim throws carefully. Hatchets can hit across open areas and through windows.","Beast of Prey · Territorial Imperative · Hex: Huntress Lullaby","Original"]'::jsonb, 7),
('killers:the-cannibal', 'killers', '["The Cannibal","Bubba Sawyer","Easy","Bubba’s Chainsaw","A close-range chainsaw Killer who can threaten multiple survivors in a sweeping attack.","Rev the chainsaw to perform a sweeping charge. Manage the power carefully around obstacles.","Knock Out · Barbecue & Chili · Franklin’s Demise","The Texas Chain Saw Massacre"]'::jsonb, 8),
('killers:the-nightmare', 'killers', '["The Nightmare","Freddy Krueger","Hard","Dream Demon","A dream-themed Killer who pressures survivors through the Dream World.","Survivors enter the Dream World over time. Freddy can use dream snares or other dream interactions to slow and locate them.","Fire Up · Remember Me · Blood Warden","A Nightmare on Elm Street"]'::jsonb, 9),
('killers:the-pig', 'killers', '["The Pig","Amanda Young","Intermediate","Jigsaw’s Baptism","A stealth and slowdown Killer who uses ambushes and reverse bear traps.","Crouch to reduce her presence, ambush around loops, and use reverse bear traps to create timed objective pressure.","Hangman’s Trick · Surveillance · Make Your Choice","SAW"]'::jsonb, 10),
('killers:the-clown', 'killers', '["The Clown","Jeffrey Hawk","Intermediate","The Afterpiece Tonic","A zone-control Killer who throws bottles that affect movement and visibility.","Use purple tonic to hinder survivors and yellow antidote to gain a speed boost. Bottle placement matters.","Bamboozle · Coulrophobia · Pop Goes the Weasel","Original"]'::jsonb, 11),
('killers:the-spirit', 'killers', '["The Spirit","Rin Yamaoka","Hard","Yamaoka’s Haunting","A mind-game Killer who phases to move quickly while relying on sound and prediction.","Phase out of sight and listen for survivor movement. Predict routes to reappear close to a target.","Spirit Fury · Hex: Haunted Ground · Rancor","Original"]'::jsonb, 12),
('killers:the-legion', 'killers', '["The Legion","Frank, Julie, Susie & Joey","Intermediate","Feral Frenzy","A fast-paced group of Killers who use a frenzy to chain hits and pressure the team.","Activate Feral Frenzy to sprint and vault quickly. Hitting survivors applies Deep Wound and can reveal others.","Discordance · Mad Grit · Iron Maiden","Original"]'::jsonb, 13),
('killers:the-plague', 'killers', '["The Plague","Adiris","Intermediate","Vile Purge","A ranged infection Killer who contaminates survivors and objects.","Use Vile Purge to infect survivors and objects. Survivors can cleanse, giving her access to a stronger Corrupt Purge.","Corrupt Intervention · Infectious Fright · Dark Devotion","Original"]'::jsonb, 14),
('killers:the-ghost-face', 'killers', '["The Ghost Face","Danny Johnson","Hard","Night Shroud","A stealth Killer who stalks survivors and can approach without a terror warning.","Use Night Shroud to hide your presence, lean to stalk, and expose survivors who are fully marked.","I’m All Ears · Thrilling Tremors · Furtive Chase","Scream"]'::jsonb, 15),
('killers:the-demogorgon', 'killers', '["The Demogorgon","The Demogorgon","Intermediate","Of the Abyss","A predatory creature that can travel through portals and launch a powerful pounce.","Create portals to move between areas, detect nearby survivors around active portals, and use Shred for a lunge attack.","Surge · Mindbreaker · Cruel Limits","Stranger Things"]'::jsonb, 16),
('killers:the-oni', 'killers', '["The Oni","Kazan Yamaoka","Hard","Yamaoka Blade","A powerful Killer who gathers blood energy from injured survivors.","Collect Blood Orbs to activate Blood Fury, then use a fast demon dash and powerful strike.","Zanshin Tactics · Blood Echo · Nemesis","Original"]'::jsonb, 17),
('killers:the-deathslinger', 'killers', '["The Deathslinger","Caleb Quinn","Intermediate","The Redeemer","A ranged Killer who fires a harpoon to reel survivors toward him.","Aim and fire the Redeemer to spear a survivor, then reel them in while managing obstacles and line tension.","Gearhead · Dead Man’s Switch · Hex: Retribution","Original"]'::jsonb, 18),
('killers:the-executioner', 'killers', '["The Executioner","Pyramid Head","Intermediate","Rites of Judgement","A zone-control Killer whose attacks can travel through obstacles and mark survivors.","Drag the blade to create trails, then use Punishment of the Damned for a ranged ground attack.","Forced Penance · Trail of Torment · Deathbound","Silent Hill"]'::jsonb, 19),
('killers:the-blight', 'killers', '["The Blight","Talbot Grimes","Hard","Blighted Corruption","A high-mobility Killer who rushes between surfaces and attacks after bouncing.","Rush into obstacles to chain bounces, then use a lethal rush attack. Map knowledge is important.","Dragon’s Grip · Hex: Blood Favor · Hex: Undying","Original"]'::jsonb, 20),
('killers:the-twins', 'killers', '["The Twins","Charlotte & Victor Deshayes","Hard","Blood Bond","A duo Killer who can switch between Charlotte and her smaller twin Victor.","Control Charlotte for normal movement or release Victor to scout and pounce. Switching at the right time is key.","Hoarder · Oppression · Coup de Grâce","Original"]'::jsonb, 21),
('killers:the-trickster', 'killers', '["The Trickster","Ji-Woon Hak","Easy","Showstopper","A ranged Killer who throws multiple blades to pressure survivors in open areas.","Throw blades to build up the laceration meter. Accurate repeated hits trigger a damaging effect.","Starstruck · Hex: Crowd Control · No Way Out","Original"]'::jsonb, 22),
('killers:the-nemesis', 'killers', '["The Nemesis","Nemesis T-Type","Intermediate","T-Virus","A relentless Killer whose tentacle attack spreads infection and breaks obstacles.","Use the tentacle to infect and strike survivors. Zombies patrol the map and can pressure survivors.","Lethal Pursuer · Hysteria · Eruption","Resident Evil"]'::jsonb, 23),
('killers:the-cenobite', 'killers', '["The Cenobite","Elliot Spencer","Hard","Summons of Pain","A chain-focused Killer who uses summoned chains and a puzzle box to pressure the team.","Summon chains to hinder survivors. The Lament Configuration can trigger a chain hunt if left unattended.","Deadlock · Hex: Plaything · Scourge Hook: Gift of Pain","Hellraiser"]'::jsonb, 24),
('killers:the-artist', 'killers', '["The Artist","Carmina Mora","Intermediate","Birds of Torment","A ranged information and zoning Killer who commands flocks of Dire Crows.","Place and launch crows to threaten lanes and reveal survivors hit at a distance.","Grim Embrace · Scourge Hook: Pain Resonance · Hex: Pentimento","Original"]'::jsonb, 25),
('killers:the-onryo', 'killers', '["The Onryō","Sadako Yamamura","Intermediate","Deluge of Fear","A supernatural stealth Killer who uses televisions and cursed videotapes to move around the map.","Manifest and demanifest to change visibility, teleport through televisions, and build Condemned pressure.","Scourge Hook: Floods of Rage · Call of Brine · Merciless Storm","Ringu"]'::jsonb, 26)
